85 
86 class GpuCtx
87 {
88     friend class GpuCtxScope;
89 
90     enum { QueryCount = 64 * 1024 };
91 
92 public:
93     GpuCtx()
94         : m_context( GetGpuCtxCounter().fetch_add( 1, std::memory_order_relaxed ) )
95         , m_head( 0 )
96         , m_tail( 0 )
97     {
98         assert( m_context != 255 );
99 
100         glGenQueries( QueryCount, m_query );
101 
102         int64_t tgpu;
103         glGetInteger64v( GL_TIMESTAMP, &tgpu );
104         int64_t tcpu = Profiler::GetTime();
105 
106         GLint bits;
107         glGetQueryiv( GL_TIMESTAMP, GL_QUERY_COUNTER_BITS, &bits );
108 
109         const float period = 1.f;
110         const auto thread = GetThreadHandle();
111         TracyLfqPrepare( QueueType::GpuNewContext );
112         MemWrite( &item->gpuNewContext.cpuTime, tcpu );
113         MemWrite( &item->gpuNewContext.gpuTime, tgpu );
114         MemWrite( &item->gpuNewContext.thread, thread );
115         MemWrite( &item->gpuNewContext.period, period );
116         MemWrite( &item->gpuNewContext.context, m_context );
117         MemWrite( &item->gpuNewContext.flags, uint8_t( 0 ) );
118         MemWrite( &item->gpuNewContext.type, GpuContextType::OpenGl );
119 
120 #ifdef TRACY_ON_DEMAND
121         GetProfiler().DeferItem( *item );
122 #endif
123 
124         TracyLfqCommit;
125     }
126 
127     void Name( const char* name, uint16_t len )
128     {
129         auto ptr = (char*)tracy_malloc( len );
130         memcpy( ptr, name, len );
131 
132         TracyLfqPrepare( QueueType::GpuContextName );
133         MemWrite( &item->gpuContextNameFat.context, m_context );
134         MemWrite( &item->gpuContextNameFat.ptr, (uint64_t)ptr );
135         MemWrite( &item->gpuContextNameFat.size, len );
136 #ifdef TRACY_ON_DEMAND
137         GetProfiler().DeferItem( *item );
138 #endif
139         TracyLfqCommit;
140     }
141 
142     void Collect()
143     {
144         ZoneScopedC( Color::Red4 );
145 
146         if( m_tail == m_head ) return;
147 
148 #ifdef TRACY_ON_DEMAND
149         if( !GetProfiler().IsConnected() )
150         {
151             m_head = m_tail = 0;
152             return;
153         }
154 #endif
155 
156         while( m_tail != m_head )
157         {
158             GLint available;
159             glGetQueryObjectiv( m_query[m_tail], GL_QUERY_RESULT_AVAILABLE, &available );
160             if( !available ) return;
161 
162             uint64_t time;
163             glGetQueryObjectui64v( m_query[m_tail], GL_QUERY_RESULT, &time );
164 
165             TracyLfqPrepare( QueueType::GpuTime );
166             MemWrite( &item->gpuTime.gpuTime, (int64_t)time );
167             MemWrite( &item->gpuTime.queryId, (uint16_t)m_tail );
168             MemWrite( &item->gpuTime.context, m_context );
169             TracyLfqCommit;
170 
171             m_tail = ( m_tail + 1 ) % QueryCount;
172         }
173     }
174 
175 private:
176     tracy_force_inline unsigned int NextQueryId()
177     {
178         const auto id = m_head;
179         m_head = ( m_head + 1 ) % QueryCount;
180         assert( m_head != m_tail );
181         return id;
182     }
183 
184     tracy_force_inline unsigned int TranslateOpenGlQueryId( unsigned int id )
185     {
186         return m_query[id];
187     }
188 
189     tracy_force_inline uint8_t GetId() const
190     {
191         return m_context;
192     }
193 
194     unsigned int m_query[QueryCount];
195     uint8_t m_context;
196 
197     unsigned int m_head;
198     unsigned int m_tail;
199 };
200 
201 class GpuCtxScope
202 {
203 public:
204     tracy_force_inline GpuCtxScope( const SourceLocationData* srcloc, bool is_active )
205 #ifdef TRACY_ON_DEMAND
206         : m_active( is_active && GetProfiler().IsConnected() )
207 #else
208         : m_active( is_active )
209 #endif
210     {
211         if( !m_active ) return;
212 
213         const auto queryId = GetGpuCtx().ptr->NextQueryId();
214         glQueryCounter( GetGpuCtx().ptr->TranslateOpenGlQueryId( queryId ), GL_TIMESTAMP );
215 
216         TracyLfqPrepare( QueueType::GpuZoneBegin );
217         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
218         memset( &item->gpuZoneBegin.thread, 0, sizeof( item->gpuZoneBegin.thread ) );
219         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
220         MemWrite( &item->gpuZoneBegin.context, GetGpuCtx().ptr->GetId() );
221         MemWrite( &item->gpuZoneBegin.srcloc, (uint64_t)srcloc );
222         TracyLfqCommit;
223     }
224 
225     tracy_force_inline GpuCtxScope( const SourceLocationData* srcloc, int depth, bool is_active )
226 #ifdef TRACY_ON_DEMAND
227         : m_active( is_active && GetProfiler().IsConnected() )
228 #else
229         : m_active( is_active )
230 #endif
231     {
232         if( !m_active ) return;
233 
234         const auto queryId = GetGpuCtx().ptr->NextQueryId();
235         glQueryCounter( GetGpuCtx().ptr->TranslateOpenGlQueryId( queryId ), GL_TIMESTAMP );
236 
237 #ifdef TRACY_FIBERS
238         TracyLfqPrepare( QueueType::GpuZoneBegin );
239         memset( &item->gpuZoneBegin.thread, 0, sizeof( item->gpuZoneBegin.thread ) );
240 #else
241         GetProfiler().SendCallstack( depth );
242         TracyLfqPrepare( QueueType::GpuZoneBeginCallstack );
243         MemWrite( &item->gpuZoneBegin.thread, GetThreadHandle() );
244 #endif
245         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
246         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
247         MemWrite( &item->gpuZoneBegin.context, GetGpuCtx().ptr->GetId() );
248         MemWrite( &item->gpuZoneBegin.srcloc, (uint64_t)srcloc );
249         TracyLfqCommit;
250     }
251 
252     tracy_force_inline GpuCtxScope( uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, bool is_active )
253 #ifdef TRACY_ON_DEMAND
254         : m_active( is_active && GetProfiler().IsConnected() )
255 #else
256         : m_active( is_active )
257 #endif
258     {
259         if( !m_active ) return;
260 
261         const auto queryId = GetGpuCtx().ptr->NextQueryId();
262         glQueryCounter( GetGpuCtx().ptr->TranslateOpenGlQueryId( queryId ), GL_TIMESTAMP );
263 
264         TracyLfqPrepare( QueueType::GpuZoneBeginAllocSrcLoc );
265         const auto srcloc = Profiler::AllocSourceLocation( line, source, sourceSz, function, functionSz, name, nameSz );
266         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
267         memset( &item->gpuZoneBegin.thread, 0, sizeof( item->gpuZoneBegin.thread ) );
268         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
269         MemWrite( &item->gpuZoneBegin.context, GetGpuCtx().ptr->GetId() );
270         MemWrite( &item->gpuZoneBegin.srcloc, (uint64_t)srcloc );
271         TracyLfqCommit;
272     }
273 
274     tracy_force_inline GpuCtxScope( uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, int depth, bool is_active )
275 #ifdef TRACY_ON_DEMAND
276         : m_active( is_active && GetProfiler().IsConnected() )
277 #else
278         : m_active( is_active )
279 #endif
280     {
281         if( !m_active ) return;
282 
283         const auto queryId = GetGpuCtx().ptr->NextQueryId();
284         glQueryCounter( GetGpuCtx().ptr->TranslateOpenGlQueryId( queryId ), GL_TIMESTAMP );
285 
286 #ifdef TRACY_FIBERS
287         TracyLfqPrepare( QueueType::GpuZoneBeginAllocSrcLoc );
288         memset( &item->gpuZoneBegin.thread, 0, sizeof( item->gpuZoneBegin.thread ) );
289 #else
290         GetProfiler().SendCallstack( depth );
291         TracyLfqPrepare( QueueType::GpuZoneBeginAllocSrcLocCallstack );
292         MemWrite( &item->gpuZoneBegin.thread, GetThreadHandle() );
293 #endif
294         const auto srcloc = Profiler::AllocSourceLocation( line, source, sourceSz, function, functionSz, name, nameSz );
295         MemWrite( &item->gpuZoneBegin.cpuTime, Profiler::GetTime() );
296         MemWrite( &item->gpuZoneBegin.queryId, uint16_t( queryId ) );
297         MemWrite( &item->gpuZoneBegin.context, GetGpuCtx().ptr->GetId() );
298         MemWrite( &item->gpuZoneBegin.srcloc, (uint64_t)srcloc );
299         TracyLfqCommit;
300     }
301 
302     tracy_force_inline ~GpuCtxScope()
303     {
304         if( !m_active ) return;
305 
306         const auto queryId = GetGpuCtx().ptr->NextQueryId();
307         glQueryCounter( GetGpuCtx().ptr->TranslateOpenGlQueryId( queryId ), GL_TIMESTAMP );
308 
309         TracyLfqPrepare( QueueType::GpuZoneEnd );
310         MemWrite( &item->gpuZoneEnd.cpuTime, Profiler::GetTime() );
311         memset( &item->gpuZoneEnd.thread, 0, sizeof( item->gpuZoneEnd.thread ) );
312         MemWrite( &item->gpuZoneEnd.queryId, uint16_t( queryId ) );
313         MemWrite( &item->gpuZoneEnd.context, GetGpuCtx().ptr->GetId() );
314         TracyLfqCommit;
315     }
316 
317 private:
318     const bool m_active;
319 };
